import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  vec4,
  uv,
  color,
  mix,
  smoothstep
} from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;

  // 1. Root group and scene parameters
  const group = new Group();
  const width = 2.2;
  const height = 0.8;

  const palette = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. Geometry & Materials
  // We use a high resolution plane for clean edge-distance functions in shader
  const geometry = new PlaneGeometry(width, height, 32, 16);

  // Custom NodeMaterial for capsule rendering with accent edge lighting
  const material = new MeshStandardNodeMaterial({
    roughness: 0.15,
    metalness: 0.45,
    transparent: true
  });

  // Load custom capsule grain texture if available
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // TSL construction for capsule shape and interactive accent neon border
  const customNode = (() => {
    const coords = uv();
    // Transform coordinates from [0, 1] to centered [-width/2, width/2] and [-height/2, height/2]
    const x = coords.x.sub(0.5).mul(width);
    const y = coords.y.sub(0.5).mul(height);

    // Rounded rectangle / capsule SDF logic
    const radius = 0.35; // Maximum radius allowed by height
    const dx = x.abs().sub((width / 2) - radius).max(0.0);
    const dy = y.abs().sub((height / 2) - radius).max(0.0);
    const dist = dx.mul(dx).add(dy.mul(dy)).sqrt().sub(radius);

    // Outer border mask
    const isInside = smoothstep(0.015, -0.015, dist);
    // Sharp glow/edge ring
    const edgeThickness = 0.04;
    const isEdge = smoothstep(-edgeThickness - 0.01, -edgeThickness + 0.01, dist)
      .mul(smoothstep(0.01, -0.01, dist));

    // Colors mapping
    const baseColor = color(new Color(palette.surface));
    const accentColor = color(new Color(palette.accent));

    // Combine paths
    const finalColor = mix(baseColor, accentColor, isEdge);
    const finalAlpha = isInside;

    return vec4(finalColor, finalAlpha);
  })();

  material.colorNode = customNode;

  // 3. Elements assembly
  const badgeMesh = new Mesh(geometry, material);
  group.add(badgeMesh);

  // Local lights to bring out the machined-metal PBR shine
  const rimLight = new DirectionalLight(palette.paper, 1.2);
  rimLight.position.set(-2, 3, 2);
  group.add(rimLight);

  const accentLight = new DirectionalLight(palette.accent, 0.8);
  accentLight.position.set(2, -3, 1);
  group.add(accentLight);

  // 4. Text Render
  const label = ctx.fontAtlas.createText('PRICING', {
    fontSize: 0.12,
    color: palette.paper,
    align: 'center',
    letterSpacingPx: 8
  });
  // Center label inside capsule
  label.position.set(0, -0.04, 0.05);
  group.add(label);

  // 5. Actions / Animations
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(badgeMesh.position, {
    y: 0.15,
    z: 0.25,
    duration: 0.35,
    ease: 'power3.out'
  });

  const pointerOver = () => {
    hoverTl.play();
  };

  const pointerOut = () => {
    hoverTl.reverse();
  };

  const pointerDown = () => {
    gsap.to(badgeMesh.scale, {
      x: 0.94,
      y: 0.94,
      z: 0.94,
      duration: 0.12,
      ease: 'power4.out',
      yoyo: true,
      repeat: 1
    });
    ctx.emit('hub-pricing.select', { id: config.id });
  };

  // Bind input systems via userData
  group.userData = {
    handlers: {
      pointerover: pointerOver,
      pointerout: pointerOut,
      pointerdown: pointerDown
    },
    cleanup: () => {
      hoverTl.kill();
      geometry.dispose();
      material.dispose();
    }
  };

  return group;
}
